import{z as l,x as s,o as t,c as d,q as n,j as i,D as e,d as a,s as B,S as r,b as A}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"毒性流的线上检测","description":"","frontmatter":{"title":"毒性流的线上检测","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-toxicity-online.md","filePath":"quant/mm-toxicity-online.md","lastUpdated":1791063341000}'),m={name:"quant/mm-toxicity-online.md"};function p(u,E,F,c,D,C){const o=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=n('<h1 id="毒性流的线上检测" tabindex="-1">毒性流的线上检测 <a class="header-anchor" href="#毒性流的线上检测" aria-label="Permalink to &quot;毒性流的线上检测&quot;">​</a></h1><div class="epigraph"><p>误报的代价是价差收入与队列位置，漏报的代价是负的实现价差；阈值取在哪，由这两种成本的比率决定，不是由检出率决定。</p><footer>—— 据 Easley, López de Prado and O&#39;Hara, Review of Financial Studies, 2012；Cont, Kukanov and Stoikov, 2014 整理</footer></div><p><a href="/quant/mm-counterparty-tiering">上一课</a>把知情概率做成截面：不同对手不同价。但毒性还随时间起伏：同一位对手，平静时是流动性，消息前后是知情者。<a href="/quant/toxic-flow">毒性流</a>给出了保护的三档与停报价角点解；<a href="/quant/ofi-toxicity">订单流毒性</a>给出了 OFI 的研究口径。本课写线上化：检测器如何在低延迟下更新、动作如何分级、两种错误如何定价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>研究指标搬上线上隔着三件事。<strong>节拍</strong>：VPIN 在成交量钟上更新，OFI 在簿事件流上更新，markout 逐笔更新——时钟选错，指标就失去含义（口径见 <a href="/quant/event-time">事件时间</a>）。<strong>动作</strong>：检测器触发的不是「报警」而是一串降风险档位，档位要与报价引擎的接口对齐。<strong>错误成本</strong>：误报把无毒读成毒，损失价差收入与队列位置；漏报则把实现价差让给知情流。两种成本不对称，且随行情变化，所以阈值不是统计量而是决策量。</p><p><span class="marginnote">「毒性流」翻译成大白话：和你成交的对手里，有人消息比你快——你卖给他的货他知道要跌，你从他手里买的他知道要涨。这样的成交像有毒：成交后价格总朝对你不利的方向走。检测毒性就是给订单流「验毒」，决定什么时候少接单、什么时候不接单。</span></p><h3 id="信号族" tabindex="-1">信号族 <a class="header-anchor" href="#信号族" aria-label="Permalink to &quot;信号族&quot;">​</a></h3><p>四路信号并行：VPIN 在成交量桶上增量更新，桶不重算；OFI 在滚动短窗上按<a href="/quant/ofi-toxicity">订单流毒性</a>的带符号加总更新；markout 记录自己每笔成交后固定窗口的中点位移，直接对齐做市商的会计口径；账户级实现价差由正转负是最后的确认信号——前三路是预测，这一路是事实。单路信号都误报，组合用投票或加权，权重由各路的历史误报成本反推。</p><p><span class="marginnote">markout 窗口要与存货周转同量纲：平均几十秒转手的库存用 30 分钟窗口，正常的存货回复会被读成毒性，误报把全天报价拉宽，收入掉下去而库存方差几乎没降。</span></p><p><span class="marginnote">数字实例：设平均每笔赚半个价差 \\(0.02\\) 元、每分钟成交 \\(100\\) 笔。误报一次把报价拉远 \\(1\\) 分钟，少赚约 \\(2\\) 元；漏报一次放进 \\(10\\) 笔知情单、每笔让出 \\(0.10\\) 元，亏 \\(1\\) 元——成本比约 \\(2:1\\)，阈值就该偏向宁可多误报。行情一变这个比率就变，所以说阈值是决策量，不是拟合出来就一劳永逸的常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>动作分级从轻到重：缩减单笔规模、拉远报价距离、单侧停报、全停。每一档对应一个毒性置信区间，档位切换要带回滞（进入与退出阈值不同），否则信号在边界抖动时报价来回跳，队列资本被自己磨掉。验证走样本外的账户事后损益：指标拟合优度高不等于赚钱，<a href="/quant/toxic-flow">毒性流</a>已强调这是唯一的验收口径。</p><p>公告时段单独体制：消息日历提前把自动阈值挂起，宽度与在市义务按事先规则接管，不要让检测器在新闻脉冲里第一次学做事。</p>',13)),(t(),i(r,null,{default:e(()=>[B(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E7%B0%BF%E4%BA%8B%E4%BB%B6%E4%B8%8E%E6%88%90%E4%BA%A4%22%5D%20--%3E%20OFI%5B%22%E6%BB%9A%E5%8A%A8%20OFI%22%5D%0A%20%20EV%20--%3E%20VOL%5B%22%E6%88%90%E4%BA%A4%E9%87%8F%E9%92%9F%20VPIN%22%5D%0A%20%20FILL%5B%22%E8%87%AA%E8%BA%AB%E6%88%90%E4%BA%A4%22%5D%20--%3E%20MK%5B%22markout%EF%BC%9A%E5%9B%BA%E5%AE%9A%E7%AA%97%E5%8F%A3%E4%B8%AD%E7%82%B9%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20FILL%20--%3E%20RS%5B%22%E8%B4%A6%E6%88%B7%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20OFI%20--%3E%20VOTE%5B%22%E5%A4%9A%E4%BF%A1%E5%8F%B7%E6%8A%95%E7%A5%A8%22%5D%0A%20%20VOL%20--%3E%20VOTE%0A%20%20MK%20--%3E%20VOTE%0A%20%20RS%20--%3E%7C%22%E7%A1%AE%E8%AE%A4%E4%BF%A1%E5%8F%B7%22%7C%20VOTE%0A%20%20VOTE%20--%3E%20G1%5B%22%E7%BC%A9%E8%A7%84%E6%A8%A1%22%5D%0A%20%20VOTE%20--%3E%20G2%5B%22%E6%8B%89%E8%BF%9C%22%5D%0A%20%20VOTE%20--%3E%20G3%5B%22%E5%8D%95%E4%BE%A7%E5%81%9C%E6%8A%A5%22%5D%0A%20%20VOTE%20--%3E%20G4%5B%22%E5%85%A8%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("检测器处在反馈环里：你的动作改变你看到的流。停报价之后流「变干净」，可能是真的无毒了，也可能只是你不在场上——评估窗口必须包含动作后的时段，否则检测器学会了「只要停手就永远正确」。"),A("a",{href:"/quant/vpin"},"VPIN"),a(" 的钟在成交加速时加密，闪崩前典型；OFI 对撤单加速更敏感，流动性蒸发往往先撤单后成交，两路信号恰好互补，这也是不做单阈值的原因之一。")],-1)),(t(),i(r,null,{default:e(()=>[B(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9C%9F%E5%AE%9E%E8%AE%A2%E5%8D%95%E6%B5%81%22%5D%20--%3E%20D%5B%22%E6%AF%92%E6%80%A7%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%0A%20%20D%20--%3E%20ACT%5B%22%E9%99%8D%E9%A3%8E%E9%99%A9%E5%8A%A8%E4%BD%9C%EF%BC%9A%E6%8B%89%E8%BF%9C%20%2F%20%E5%81%9C%E6%8A%A5%22%5D%0A%20%20ACT%20--%3E%7C%22%E6%94%B9%E5%8F%98%E4%BD%A0%E7%9C%8B%E5%88%B0%E7%9A%84%E6%B5%81%22%7C%20F%0A%20%20ACT%20--%3E%20OBS%5B%22%E5%8A%A8%E4%BD%9C%E5%90%8E%E7%9A%84%E8%A7%82%E6%B5%8B%E6%B5%81%22%5D%0A%20%20OBS%20--%3E%20EV%5B%22%E8%AF%84%E4%BC%B0%E7%AA%97%E5%8F%A3%22%5D%0A%20%20EV%20--%3E%7C%22%E5%90%AB%E5%8A%A8%E4%BD%9C%E5%90%8E%E6%97%B6%E6%AE%B5%EF%BC%9A%E7%9F%A5%E9%81%93%E5%B9%B2%E5%87%80%E5%8F%AF%E8%83%BD%E5%8F%AA%E6%98%AF%E8%87%AA%E5%B7%B1%E7%A6%BB%E5%9C%BA%22%7C%20OK%5B%22%E9%98%88%E5%80%BC%E4%B8%8E%E6%A3%80%E5%87%BA%E7%8E%87%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20EV%20--%3E%7C%22%E4%B8%8D%E5%90%AB%E5%8A%A8%E4%BD%9C%E5%90%8E%E6%97%B6%E6%AE%B5%22%7C%20BAD%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%E5%AD%A6%E4%BC%9A%EF%BC%9A%E5%81%9C%E6%89%8B%E5%8D%B3%E6%B0%B8%E8%BF%9C%E6%AD%A3%E7%A1%AE%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：初学者挑检测器看「检出率」，越高越好。实际上检出率单独看没有信息——把所有时段都判为毒，检出率 100%，但误报成本会把全天价差收入清零。唯一的验收口径是样本外的账户事后损益：指标再漂亮，不赚钱就不合格。</span></p><p>分层的截面与检测的时序在同一账本上汇合：上一课的对手层给的是「谁常毒」，本课的信号给的是「现在毒不毒」；高毒时段里高毒层的动作最激进，低毒层仍可保留窄价差——一刀切的全局停报通常过度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>冰山与暗池使可见信号有偏，<a href="/quant/ofi-toxicity">订单流毒性</a>的测量误差讨论原样适用。市场整体波动与毒性混淆：高波动日本身会压实现价差，检测器要按波动体制分段定阈值。指标非平稳，阈值定期重估而不是一次性标定。检测的输出是风险管理语言：本课不提供识别具体自然人对手或伪装流量的构造，检测目的是让报价在毒性面前活下来，不是指控谁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线上化隔着节拍、动作与错误成本三件事；阈值是决策量，按误报与漏报成本比率定。</li><li>四路信号：VPIN、滚动 OFI、markout、账户实现价差；投票组合，最后一路是事实确认。</li><li>动作分级带回滞：缩规模、拉远、单侧停、全停，与限额接口对齐。</li><li>检测器在反馈环里：评估必须含动作后时段，否则学会「停手即正确」。</li><li>公告时段单独体制；截面分层与时序检测共用一本账。</li><li>出处：Easley, López de Prado and O&#39;Hara, <em>Review of Financial Studies</em>, 2012；Cont, Kukanov and Stoikov, <em>Journal of Financial Econometrics</em>, 2014；Glosten and Milgrom, <em>Journal of Financial Economics</em>, 1985。</li></ul>',6))])}const T=l(m,[["render",p]]);export{h as __pageData,T as default};
